SELECT QUARTER(customers.signup_date) AS signup_quarter, CASE WHEN YEAR(customers.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(customers.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, AVG(orders.shipping_fee) AS avg_shipping_fee, MIN(orders.order_date) AS first_order_date FROM orders INNER JOIN customers ON orders.customer_id = customers.id WHERE customers.is_active GROUP BY QUARTER(customers.signup_date), CASE WHEN YEAR(customers.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(customers.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END;
